public partial class DebrisBridgeOperations:RefCounted
{
    private readonly ActorAnimationOperations _animation=new();private readonly PhysicsSettingsOperations _settings=new();private readonly DestructionMaterialOperations _materials=new();private readonly DestructionAuthoringOperations _authoring=new();private readonly DestructionDefinitionOperations _definition=new();private readonly DestructionGeometryOperations _geometry=new();private readonly ModelMeshOperations _meshes=new();private readonly PhysicsCollisionWorldOperations _collision=new();private readonly PowderFluidOperations _fluid=new();private readonly FluidSolverOperations _fluidSolver=new();
    private static Settings Map(GodotObject owner,string key)=>owner.Get(key).AsGodotDictionary();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;private static Resource Actor(RefCounted controller,string id)=>Map(controller,"prototypes")[id].AsGodotDictionary()["actor"].As<Resource>();
    public void reset(RefCounted owner){foreach(var value in Map(owner,"renderers").Values){var node=value.AsGodotObject() as Node;if(GodotObject.IsInstanceValid(node))node!.Free();}foreach(string key in new[]{"bodies","renderers","meshes"})Map(owner,key).Clear();}
    public void refresh(RefCounted owner,RefCounted controller,double time){var bodies=Map(owner,"bodies");bodies.Clear();foreach(var actorId in Map(controller,"states").Keys){string id=actorId.AsString();var actor=Actor(controller,id);double local=controller.Call("_local",actor,time).AsDouble();var values=_animation.sampled_values(actor,local);var config=_settings.sample(actor,local);var material=_materials.resolve(values,Vector3.Zero);if(material!=null&&Get(values,"debris_use_material_contacts",true).AsBool()){var physical=material.Get("values").AsGodotDictionary();config["friction"]=Get(physical,"debris_friction",config["friction"]).AsDouble();config["bounce"]=Get(physical,"debris_restitution",config["bounce"]).AsDouble();}var state=Map(controller,"states")[actorId].AsGodotDictionary();foreach(var value in Get(state,"destruction_fragments",new GArray()).AsGodotArray()){var fragment=value.AsGodotDictionary();fragment["responds"]=state["active"].AsBool()&&Get(values,"debris_enabled",true).AsBool()&&(config["mode"].AsInt32() is not (3 or 4)||controller.Call("is_baking",id).AsBool());var rule=Get(Get(values,"destruction_fragments",new Settings()).AsGodotDictionary(),_authoring.fragment_key(id,fragment["id"].AsString()),new Settings()).AsGodotDictionary();local=controller.Call("_local",actor,time).AsDouble();if(Get(rule,"enabled",true).AsBool()&&(local<Get(rule,"pin_until",-1).AsDouble()||(Get(rule,"mode",0).AsInt32()==2&&local>=Get(rule,"from",0).AsDouble()&&(Get(rule,"to",-1).AsDouble()<0||local<rule["to"].AsDouble()))))fragment["responds"]=false;bodies[fragment["id"]]=new Settings{["state"]=fragment,["owner"]=id,["config"]=config,["values"]=values};}}}
    public Settings lookup(RefCounted owner,RefCounted controller,string id){var bodies=Map(owner,"bodies");return bodies.ContainsKey(id)?bodies[id].AsGodotDictionary()["state"].AsGodotDictionary():Get(Map(controller,"states"),id,new Settings()).AsGodotDictionary();}
    public Settings settings(RefCounted owner,RefCounted controller,string id,double time){var bodies=Map(owner,"bodies");if(bodies.ContainsKey(id)){var entry=bodies[id].AsGodotDictionary();var config=entry["config"].AsGodotDictionary().Duplicate();config["mass"]=entry["state"].AsGodotDictionary()["mass"];return config;}if(Map(controller,"prototypes").ContainsKey(id)){var actor=Actor(controller,id);return _settings.sample(actor,controller.Call("_local",actor,time).AsDouble());}return GD.Load<GDScript>("res://scripts/actors/physics/physics_settings.gd").GetScriptConstantMap()["DEFAULTS"].AsGodotDictionary();}
    public void emit(RefCounted owner,RefCounted controller,string actorId,string source,string kind,double time,Vector3 point,Vector3 normal,Vector3 velocity,double energy){var states=Map(controller,"states");if(!states.ContainsKey(actorId)||energy<.02)return;var state=states[actorId].AsGodotDictionary();string stamp=source+":"+kind;var recent=Get(state,"debris_recent",new Settings()).AsGodotDictionary();if(time-Get(recent,stamp,-100).AsDouble()<.15)return;recent[stamp]=time;state["debris_recent"]=recent;while(recent.Count>512)recent.Remove(recent.Keys.First());var events=Get(state,"destruction_events",new GArray()).AsGodotArray();while(events.Count>=96)events.RemoveAt(0);string id=stamp+":"+(long)Math.Round(time*controller.Get("rate").AsDouble(),MidpointRounding.AwayFromZero);var item=new Settings{["id"]=id,["source_actor"]=actorId,["fragment"]=source,["type"]=kind,["time"]=time,["point"]=point,["normal"]=normal,["velocity"]=velocity,["energy"]=energy,["seed"]=(long)GD.Hash(id)};events.Add(item);state["destruction_events"]=events;controller.EmitSignal("destruction_event",item);}
    public GArray secondary(RefCounted owner,RefCounted controller,Settings entry,Settings parent,Settings hit,double energy,double time){var material=_materials.resolve(entry["values"].AsGodotDictionary(),Vector3.Zero);var pose=parent["pose"].AsTransform3D();var impact=new Settings{["energy"]=energy,["normal"]=pose.Basis.Inverse()*hit["normal"].AsVector3(),["local_point"]=pose.AffineInverse()*hit["point"].AsVector3()};var parentMesh=parent["mesh"].As<Resource>();var size=_meshes.bounds(parentMesh).Size;var operation=material!=null?_materials.response(material,impact,new Settings(),size[(int)size.MinAxisIndex()]):_definition.operation(2,0);if(operation.Count==0||operation["type"].AsInt32() is not (0 or 2))return new GArray();operation["position"]=impact["local_point"];operation["direction"]=impact["normal"];operation["pieces"]=Math.Clamp(Get(operation,"pieces",3).AsInt32(),2,4);operation["seed"]=(long)GD.Hash(parent["id"].AsString()+Get(parent,"depth",0).AsInt64());var output=_geometry.evaluate(parentMesh,new Settings{["secondary"]=operation},Map(controller,"states")[entry["owner"]].AsGodotDictionary()["destruction_geometry"].AsGodotDictionary()["materials"].AsGodotArray().Count);if(output["error"].AsString().Length>0)return new GArray();var parts=output["parts"].AsGodotArray();if(parts.Count<2)return new GArray();double total=0;foreach(var value in parts)total+=_geometry.volume(value.As<Resource>());var children=new GArray();for(int i=0;i<parts.Count;i++){var mesh=_meshes.copy_mesh(parts[i].As<Resource>());var center=_meshes.bounds(mesh).GetCenter();double volume=_geometry.volume(mesh);var vertices=mesh.Get("vertices").AsVector3Array();for(int j=0;j<vertices.Length;j++)vertices[j]-=center;mesh.Set("vertices",vertices);var offset=pose.Basis*center;children.Add(new Settings{["id"]=parent["id"].AsString()+":s"+i,["mesh"]=mesh,["pose"]=pose*new Transform3D(Basis.Identity,center),["v"]=parent["v"].AsVector3()+parent["w"].AsVector3().Cross(offset),["w"]=parent["w"],["mass"]=parent["mass"].AsDouble()*volume/Math.Max(.000001,total),["sleep"]=0.0,["depth"]=Get(parent,"depth",0).AsInt32()+1,["structure_origin"]=Get(parent,"structure_origin",Vector3.Zero).AsVector3()+center});}emit(owner,controller,entry["owner"].AsString(),parent["id"].AsString(),"secondary",time,hit["point"].AsVector3(),hit["normal"].AsVector3(),parent["v"].AsVector3(),energy);return children;}
}
